package main

import (
	"regexp"
	"strconv"
)

func ValidatePESEL(pesel string) bool {
	if matched, _ := regexp.MatchString(`^\d{11}$`, pesel); !matched {
		return false
	}
	weights := []int{1, 3, 7, 9, 1, 3, 7, 9, 1, 3}
	sum := 0
	for i := 0; i < 10; i++ {
		digit, _ := strconv.Atoi(string(pesel[i]))
		sum += digit * weights[i]
	}
	checksum := (10 - (sum % 10)) % 10
	lastDigit, _ := strconv.Atoi(string(pesel[10]))
	return checksum == lastDigit
}

