pub fn validate_pesel(pesel: &str) -> bool {
    if pesel.len() != 11 || !pesel.chars().all(|c| c.is_ascii_digit()) {
        return false;
    }
    let weights = [1, 3, 7, 9, 1, 3, 7, 9, 1, 3];
    let digits: Vec<u32> = pesel.chars().map(|c| c.to_digit(10).unwrap()).collect();
    let sum: u32 = digits.iter().take(10).zip(weights.iter()).map(|(&d, &w)| d * w).sum();
    let checksum = (10 - (sum % 10)) % 10;
    checksum == digits[10]
}
